import{_ as e,o as t,c as p,a5 as o}from"./chunks/framework.bIR-4glx.js";const h=JSON.parse('{"title":"简单介绍下去年和现在的我","description":"一篇关于毕业、回家、首个网站与早期创业的 2016 年历史文章。","frontmatter":{"title":"简单介绍下去年和现在的我","description":"一篇关于毕业、回家、首个网站与早期创业的 2016 年历史文章。","updated":"2026-09-01T00:00:00.000Z"},"headers":[],"relativePath":"threads/archive/last-year-and-now.md","filePath":"threads/archive/last-year-and-now.md","lastUpdated":1788220800000}'),r={name:"threads/archive/last-year-and-now.md"};function n(s,a,c,d,l,i){return t(),p("div",null,[...a[0]||(a[0]=[o('<h1 id="简单介绍下去年和现在的我" tabindex="-1">简单介绍下去年和现在的我 <a class="header-anchor" href="#简单介绍下去年和现在的我" aria-label="Permalink to &quot;简单介绍下去年和现在的我&quot;">​</a></h1><p><strong>编者说明（2026-08-31）：</strong> 文中的自我介绍、项目、公司、收入与身体状况都属于 2016 年的时间切片，不代表作者当前状态，也不构成创业、投资或职业建议。读者应把它当作回望材料，而不是可直接复制的路线图。</p><blockquote><p>原文日期：2016-04-24（按可恢复的 Wayback 快照标注） 归档来源：原 Wayback Machine 快照当前返回 404；本页保留仓库中的历史文本，不把失效地址当作可复查证据。</p></blockquote><p>去年我大四。2015年3月7号我去了北京，本来是去找实习的，但成功率较高的面试给了我自信，我胃口变大，然后一直在面试...两个月大部分的时间都在面试。</p><p>正当我准备入职汽车之家之际，学校那边让我立马返校，因为我没有参加中期答辩，终辩再不去，那毕业证就不用拿了。</p><p>考虑到大四上学期重修13门课的确是为了能顺利毕业，就返校了。答辩的时候我坦言自己的电路板是淘宝买的，导致二辩。二辩在老师的指导下重做，完成了项目要求的大部分功能，加上答辩时临时发挥得还不错，也就过了。</p><p>毕业后我并没有如期拿到毕业证，因为大三时有两个实习没有参加，需要等下一年跟下一届做。然后我就回了老家。</p><p>呆在家的这段时间，发生了很多事情。只记重要的两件：一件是学会了做饭，另一件是得了关节炎。</p><p>2016开始，我决定不再颓废，开始捣鼓一个电影网站。折腾了一段时间，bt0.com（bt零）收获了第一批用户，用户反馈还不错。</p><p>之后接到了几个网站设计的单子，赚了点零花钱，然后我和初中同学翔子开始了创业之旅。</p><p>我们在3月份有了第一家公司，4月份在沈阳成立了另一家互联网公司，现在在南京申请第三家公司，公司的名字就用我一直很喜欢的“玩有引力”。</p><p>短时间内，我们的发展的确很快，不过这都是有准备的。只能说厚积薄发，低调行事。</p><p>在这里要感谢阿其哥哥、翔子，还有我的亲弟弟。</p><p>现在的我拥有两家规模不大的互联网公司，主营业务分别是比特币和游戏娱乐行业。</p><p>今年是本命年了，想踏踏实实把事情做好，不冒进，少装逼。</p><h2 id="原文评论" tabindex="-1">原文评论 <a class="header-anchor" href="#原文评论" aria-label="Permalink to &quot;原文评论&quot;">​</a></h2><p>不可能不确定：</p><blockquote><p>bt0 太赞了，就凭这网站，你这牛B不是白吹的。</p></blockquote>',18)])])}const u=e(r,[["render",n]]);export{h as __pageData,u as default};
